rule "sudo_event_outcome"
when
    has_field("application_name") &&
    to_string($message.application_name) == "sudo" &&
    has_field("process_command_line")
then
    let has_error = has_field("vendor_sudo_error");
    let outcomes = key_value("true=failure false=success");
    set_field("event_outcome", to_string(outcomes.to_string(has_error)));
end

rule "pam_extract_fields"
when
    regex("^pam_[a-z0-9_]+\\(", to_string($message.message)).matches == true
then
    let fields = grok("^%{DATA:vendor_pam_module}\\(%{DATA:vendor_pam_service_name}:%{DATA:vendor_pam_function}\\)\\s*:\\s*%{GREEDYDATA:message}$",
    to_string($message.message));
    set_fields(fields);
end

rule "ssh_vendor_credential_type"
when
    has_field("application_name") &&
    to_string($message.application_name) == "sshd" &&
    has_field("vendor_event_description")
then
    let field = regex("^(Accepted|Failed)\\s+(password|publickey)$",
    to_string($message.vendor_event_description));
    set_field("vendor_credential_type", field["1"]);
end

rule "ssh_access_control"
when
    has_field("application_name") &&
    to_string($message.application_name) == "sshd"
then
    let fields = grok("^User\\s+%{USERNAME:user_name}\\s+from\\s+%{DATA:source_ip}\\s+%{DATA:vendor_event_outcome}\\s+because\\s+%{DATA:vendor_event_outcome_reason}$",
    to_string($message.message));
    set_fields(fields);
end

rule "chfn_user_information_changed"
when
    has_field("application_name") &&
    to_string($message.application_name) == "chfn" &&
    regex("^changed\\s+user\\s+'\\w+'", to_string($message.message)).matches == true
then
    let fields = grok("^changed\\s+user\\s+'%{USERNAME:user_name}'\\s+information$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "Changed user information");
end

rule "auth_log_extract_fields"
when
    has_field("filebeat_log_file") &&
    to_string($message.filebeat_log_file) == "auth.log"
then
    let fields = grok("^%{DATA:event_created}\\s+%{HOSTNAME:event_source}\\s+(?:\\()?%{DATA:application_name}(?:\\))?(?:\\[%{POSINT:process_id}\\])?\\s*:\\s*%{GREEDYDATA:message}$",
    to_string($message.message));
    set_fields(fields);
    set_field("application_name", lowercase(to_string($message.application_name)));
end

rule "groupdel_shadow_group_removed"
when
    has_field("application_name") &&
    to_string($message.application_name) == "groupdel" &&
    regex("removed\\s+from\\s+/etc/gshadow", to_string($message.message)).matches == true
then
    let fields = grok("^group\\s+'%{USERNAME:vendor_group_name}'\\s+removed\\s+from\\s+/etc/gshadow$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "Shadow group removed");
end

rule "ssh_event_outcome"
when
    has_field("application_name") &&
    to_string($message.application_name) == "sshd" &&
    has_field("vendor_event_description")
then
    let is_accepted = contains(to_string($message.vendor_event_description), "Accepted");
    let outcomes = key_value("true=success false=failure");
    set_field("event_outcome", to_string(outcomes.to_string(is_accepted)));
end

rule "ssh_extract_fields"
when
    has_field("application_name") &&
    to_string($message.application_name) == "sshd"
then
    let fields = grok("^%{DATA:vendor_event_description}\\s+for\\s+(?:invalid\\s+user\\s+)?%{USERNAME:user_name}\\s+from\\s+%{IPV4:source_ip}\\s+port\\s+%{POSINT:source_port}\\s+ssh2(?:\\s*:\\s*)?(?:%{DATA:vendor_ssh_signature})?$",
    to_string($message.message));
    set_fields(fields);
end

rule "groupadd_shadow_group_added"
when
    has_field("application_name") &&
    to_string($message.application_name) == "groupadd" &&
    regex("^group\\s+added\\s+to\\s+/etc/gshadow\\s*:", to_string($message.message)).matches == true
then
    let fields = grok("^group\\s+added\\s+to\\s+/etc/gshadow\\s*:\\s*name=%{USERNAME:vendor_group_name}$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "Shadow group added");
end

rule "passwd_password_changed"
when
    has_field("application_name") &&
    to_string($message.application_name) == "passwd" &&
    regex("^password\\s+changed\\s+for", to_string($message.message)).matches == true
then
    let fields = grok("^password\\s+changed\\s+for\\s+%{USERNAME:user_name}$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "User password changed");
end

rule "useradd_user_created"
when
    has_field("application_name") &&
    to_string($message.application_name) == "useradd" &&
    regex("^new\\s+user\\s*:", to_string($message.message)).matches == true
then
    let fields = grok("^new\\s+user\\s*:\\s*name=%{USERNAME:user_name}\\s*,\\s*UID=%{POSINT:user_id}\\s*,\\s*GID=%{POSINT:vendor_group_id}\\s*,\\s*home=%{DATA:vendor_user_home}\\s*,\\s*shell=%{DATA:vendor_user_shell}\\s*,\\s*from=%{DATA:vendor_tty}$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "User created");
end

rule "groupadd_group_added"
when
    has_field("application_name") &&
    to_string($message.application_name) == "groupadd" &&
    regex("^group\\s+added\\s+to\\s+/etc/group\\s*:", to_string($message.message)).matches == true
then
    let fields = grok("^group\\s+added\\s+to\\s+/etc/group\\s*:\\s*name=%{USERNAME:vendor_group_name}\\s*,\\s*GID=%{POSINT:vendor_group_id}$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "Group added");
end

rule "pam_auth_extract_fields"
when
    has_field("vendor_pam_function") &&
    to_string($message.vendor_pam_function) == "auth"
then
    let fields = grok("^authentication\\s+%{WORD:event_outcome}\\s*;\\s*logname=%{DATA:vendor_pam_logname}\\s+uid=%{DATA:vendor_pam_uid}\\s+euid=%{DATA:vendor_pam_euid}\\s+tty=%{DATA:vendor_tty}\\s+ruser=%{DATA:source_user_name}\\s+rhost=%{DATA:source_ip}(?:\\s+user=%{GREEDYDATA:user_name})?$",
    to_string($message.message));
    set_fields(fields);
end

rule "chsh_user_shell_changed"
when
    has_field("application_name") &&
    to_string($message.application_name) == "chsh" &&
    regex("^changed\\s+user\\s+'\\w+'\\s+shell", to_string($message.message)).matches == true
then
    let fields = grok("^changed\\s+user\\s+'%{USERNAME:user_name}'\\s+shell\\s+to\\s+'%{DATA:vendor_user_shell}'$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "Changed user shell");
end

rule "userdel_user_deleted"
when
    has_field("application_name") &&
    to_string($message.application_name) == "userdel" &&
    regex("^delete\\s+user", to_string($message.message)).matches == true
then
    let fields = grok("^delete\\s+user\\s+'%{USERNAME:user_name}'$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "User deleted");
end

rule "usermod_user_id_changed"
when
    has_field("application_name") &&
    to_string($message.application_name) == "usermod" &&
    regex("^change\\s+user\\s+'\\w+'\\s+UID\\s+from", to_string($message.message)).matches == true
then
    let fields = grok("^change\\s+user\\s+'%{USERNAME:user_name}'\\s+UID\\s+from\\s+'%{POSINT:source_user_id}'\\s+to\\s+'%{POSINT:user_id}'$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "User ID changed");
end

rule "groupadd_group_created"
when
    has_field("application_name") &&
    (to_string($message.application_name) == "groupadd" ||
    to_string($message.application_name) == "useradd") &&
    regex("^new\\s+group\\s*:", to_string($message.message)).matches == true
then
    let fields = grok("^new\\s+group\\s*:\\s*name=%{USERNAME:vendor_group_name}\\s*,\\s*GID=%{POSINT:vendor_group_id}$",
    to_string($message.message));
    set_fields(fields);
    set_field("vendor_event_description", "Group created");
end

rule "ssh_source_hostname"
when
    has_field("application_name") &&
    to_string($message.application_name) == "sshd" &&
    has_field("source_ip")
then
    let raw = to_string(lookup_value("dns_reverse_lookup", $message.source_ip));
    let without_dot = substring(raw, 0, length(raw) - 1);
    let hostname = lowercase(without_dot);
    set_field("source_hostname", hostname);
end

rule "sudo_extract_fields"
when
    has_field("application_name") &&
    to_string($message.application_name) == "sudo"
then
    let fields = grok("^%{USERNAME:source_user_name}\\s*:\\s*(?:%{DATA:vendor_sudo_error})?(?:\\s*;\\s*)?(?:TTY=%{DATA:vendor_tty})?(?:\\s*;\\s*)?PWD=%{DATA:process_working_directory}\\s*;\\s*USER=%{USERNAME:user_name}\\s*;\\s*COMMAND=%{GREEDYDATA:process_command_line}$",
    to_string($message.message));
    set_fields(fields);
end
